#!/usr/bin/env node

import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { mergeRoutedEventProgressState, scheduledIdsDueByTurnEnd } from '../../lib/event-progress.js';
import { minutesUntilEventConsequence } from '../../lib/event-consequence.js';
import { buildSceneMomentumDirective, classifySceneIntent, isPcRelevantScheduleEvent, nextScheduleBoundaryMinutes, scheduleBoundaryLimitMinutes } from '../../lib/scene-momentum.js';
import { isAdditiveAdverbialStem } from '../../lib/time-plan-parser.js';

const source=readFileSync('api/chat-router.js','utf8');
const start=source.indexOf('function bounded(');
const end=source.indexOf('function uniqText(');
assert.ok(start>=0&&end>start,'Scene Momentum time-floor source markers missing');
const timeFloorSource=source.slice(start,end);
const makeHelpers=new Function('array','object','classifySceneIntent','isPcRelevantScheduleEvent','nextScheduleBoundaryMinutes','scheduleBoundaryLimitMinutes','scheduledIdsDueByTurnEnd','minutesUntilEventConsequence','CHARACTER_REGISTRY','isAdditiveAdverbialStem',`${timeFloorSource}\nreturn {applySceneMomentumTimeFloor,consequenceNpcKeysForShortening,consequenceNpcEffectsForShortening,deriveTimedActionRuntime,runtimeSynthesisTurn,prefixNpcStateUpdate};`);
const array=(value)=>Array.isArray(value)?value:[];
const object=(value)=>value&&typeof value==='object'&&!Array.isArray(value)?value:{};
const testRegistry={artemis:'아르테미스',emily:'에밀리'};
const {applySceneMomentumTimeFloor,consequenceNpcKeysForShortening,consequenceNpcEffectsForShortening,deriveTimedActionRuntime,runtimeSynthesisTurn,prefixNpcStateUpdate}=makeHelpers(array,object,classifySceneIntent,isPcRelevantScheduleEvent,nextScheduleBoundaryMinutes,scheduleBoundaryLimitMinutes,scheduledIdsDueByTurnEnd,minutesUntilEventConsequence,testRegistry,isAdditiveAdverbialStem);

const knightPc={name:'카인',department:'기사과'};
const irrelevantScheduleSave={
  pc:knightPc,
  world:{date:'1285-03-01',time:'09:50'},
  scheduleContext:{due:[],upcoming:[
    {id:'npc-briefing',title:'아르테미스 교관 회의',date:'1285-03-01',time:'09:54',participants:['artemis']},
    {id:'world-bell',title:'서문 종각 타종',date:'1285-03-01',time:'09:55',kind:'world',participants:[]},
    {id:'magic-class',title:'마법과 필수 수업',date:'1285-03-01',time:'09:56',kind:'academic',participants:['elena']},
    {id:'knight-class',title:'기사과 필수 수업',date:'1285-03-01',time:'10:00',kind:'academic',participants:['artemis']},
  ]},
};
assert.equal(isPcRelevantScheduleEvent(irrelevantScheduleSave,irrelevantScheduleSave.scheduleContext.upcoming[0]),false,'an NPC-only legacy row must not constrain the PC clock');
assert.equal(isPcRelevantScheduleEvent(irrelevantScheduleSave,{id:'npc-owned-briefing',title:'레나 개인 일정',owner:'npc:lena',participants:['lena']}),false,'an NPC owner namespace containing the letters pc must not become a PC schedule boundary');
assert.equal(isPcRelevantScheduleEvent(irrelevantScheduleSave,{id:'pc-owned-briefing',title:'카인 개인 일정',owner:'pc:cain'}),true,'a delimited PC owner identity remains authoritative');
assert.equal(isPcRelevantScheduleEvent(irrelevantScheduleSave,irrelevantScheduleSave.scheduleContext.upcoming[1]),false,'a world-only event must progress independently');
assert.equal(isPcRelevantScheduleEvent(irrelevantScheduleSave,irrelevantScheduleSave.scheduleContext.upcoming[2]),false,'another department schedule must not constrain this PC');
assert.equal(isPcRelevantScheduleEvent(irrelevantScheduleSave,irrelevantScheduleSave.scheduleContext.upcoming[3]),true,'the PC department schedule remains authoritative');
assert.equal(isPcRelevantScheduleEvent(irrelevantScheduleSave,{id:'personal-magic-visit',title:'마법과 건물 개인 면담',kind:'personal',participants:['elena']}),true,'a personal PC appointment stays relevant even when its location names another department');
assert.equal(isPcRelevantScheduleEvent(irrelevantScheduleSave,{id:'joint-class',title:'기사과·마법과 합동 수업',kind:'academic',participants:['artemis','elena']}),true,'a cross-department academic event remains relevant to every named department');
assert.equal(nextScheduleBoundaryMinutes(irrelevantScheduleSave,{futureOnly:true}),10,'only the next PC-relevant schedule may become a hard stop');

const shortTravelSave={pc:knightPc,world:{date:'1285-03-01',time:'09:40'},scheduleContext:{due:[],upcoming:[{id:'knight-class',title:'기사과 필수 수업',date:'1285-03-01',time:'10:00',kind:'academic'}]}};
const shortTravelDirective=buildSceneMomentumDirective({action:'도서관에 간다.',saveState:shortTravelSave});
assert.doesNotMatch(shortTravelDirective,/SCHEDULE_BOUNDARY=20min/,'a short travel estimate must not be stretched to a later schedule boundary');
assert.match(shortTravelDirective,/SCHEDULE_CAP=20min/,'a later boundary inside the travel guide is a cap, not a required target');
assert.equal(scheduleBoundaryLimitMinutes(classifySceneIntent('도서관에 간다.')),3,'short travel hard-stop targeting is bounded by its minimum completion estimate');
let shortTravelTurn={state_delta:{advance_minutes:0},choices:['수업으로 간다','도서관으로 간다','기다린다'],event_progress:{event_instance_id:'knight-class'}};
applySceneMomentumTimeFloor({action:'도서관에 간다.',saveState:shortTravelSave},shortTravelTurn,'game');
assert.equal(shortTravelTurn.state_delta.advance_minutes,0,'post-processing must not align a short action to a later cap');

const boundarySave={world:{date:'1285-03-01',time:'09:50'},scheduleContext:{due:[],upcoming:[{id:'class',date:'1285-03-01',time:'10:00'}]}};
assert.equal(nextScheduleBoundaryMinutes(boundarySave),10,'next schedule boundary should be ten minutes away');
const halfDayBoundarySave={pc:{department:'기사과'},world:{date:'1285-03-01',time:'09:00',location:'개인실'},scheduledEvents:[{id:'evening-class',title:'기사과 필수 수업',date:'1285-03-01',time:'18:00',kind:'academic',status:'scheduled'}],scheduleContext:{due:[],upcoming:[{id:'evening-class',title:'기사과 필수 수업',date:'1285-03-01',time:'18:00',kind:'academic',status:'scheduled'}]}};
assert.match(buildSceneMomentumDirective({action:'반나절 동안 잠을 잔다.',saveState:halfDayBoundarySave}),/SCHEDULE_BOUNDARY=540min/,'a schedule inside a half-day sleep must interrupt the explicit twelve-hour duration');
const daytimeBoundarySave={pc:{department:'기사과'},world:{date:'1285-03-01',time:'09:00',location:'훈련장'},scheduledEvents:[{id:'noon-class',title:'기사과 필수 수업',date:'1285-03-01',time:'12:00',kind:'academic',status:'scheduled'}],scheduleContext:{due:[],upcoming:[{id:'noon-class',title:'기사과 필수 수업',date:'1285-03-01',time:'12:00',kind:'academic',status:'scheduled'}]}};
assert.match(buildSceneMomentumDirective({action:'낮 2시에 1시간 훈련한다.',saveState:daytimeBoundarySave}),/SCHEDULE_BOUNDARY=180min/,'a noon schedule must interrupt the wait before a 낮 2시 committed activity');
const twoAmClass={id:'two-am-class',title:'기사과 새벽 수업',date:'1285-03-02',time:'02:00',kind:'academic',status:'scheduled'},twoAmSave={pc:{department:'기사과'},world:{date:'1285-03-02',time:'01:00',location:'훈련장'},scheduledEvents:[twoAmClass],scheduleContext:{due:[],upcoming:[twoAmClass]}};
let daytimeMentionTurn={scene_title:'기사과 새벽 수업',scene:[{kind:'narration',text:'낮 2시를 알리는 종이 울렸다.'}],state_delta:{advance_minutes:10},choices:['훈련을 계속한다','교관에게 묻는다','자리를 뜬다'],event_progress:null};
applySceneMomentumTimeFloor({action:'2시간 훈련한다.',saveState:twoAmSave},daytimeMentionTurn,'game');
assert.equal(daytimeMentionTurn.state_delta.advance_minutes,10,'낮 2시 narration must not be mistaken for an authoritative 02:00 boundary');
const boundedRestDirective=buildSceneMomentumDirective({action:'두 시간 쉰다.',saveState:boundarySave});
assert.match(boundedRestDirective,/SCHEDULE_BOUNDARY=10min/,'the model must receive the exact upcoming schedule boundary');
assert.match(boundedRestDirective,/120분 휴식을 경계 너머까지 실행하지 말고 10분 뒤 일정 시작 순간에서 멈춘다/,'the earlier mandatory schedule must override the longer downtime duration');
assert.match(boundedRestDirective,/SCHEDULE_BOUNDARY가 더 짧으면 그 일정 경계가 최우선/,'the explicit-duration rule must not contradict the earlier schedule boundary');
const implicitRestSave={world:{date:'1285-03-01',time:'09:25'},scheduleContext:{due:[],upcoming:[{id:'class',date:'1285-03-01',time:'10:00'}]}};
assert.match(buildSceneMomentumDirective({action:'쉰다.',saveState:implicitRestSave}),/SCHEDULE_BOUNDARY=35min/,'an implicit rest must expose any boundary reachable within its 30-240 minute guide');
assert.match(buildSceneMomentumDirective({action:'10분 기다린다.',saveState:boundarySave}),/SCHEDULE_BOUNDARY=10min/,'a boundary equal to the explicit duration must remain a hard stop');
const coincidentClass={id:'coincident-class',title:'기사과 필수 수업',date:'1285-03-01',time:'10:00',kind:'academic',status:'scheduled'},coincidentScheduleSave={pc:knightPc,world:{date:'1285-03-01',time:'09:00'},scheduledEvents:[coincidentClass],scheduleContext:{due:[],upcoming:[coincidentClass]}};
let coincidentTurn={scene:[{kind:'narration',text:'한 시간 훈련을 마쳤다.'}],state_delta:{advance_minutes:60,fatigue_delta:2,stat_progress:[{stat:'신체',amount:1}]},choices:[],event_progress:null};
const coincidentScheduleIntent=applySceneMomentumTimeFloor({action:'1시간 동안 훈련한다.',saveState:coincidentScheduleSave},coincidentTurn,'game');
assert.equal(coincidentTurn.state_delta.advance_minutes,60,'an action may complete exactly when an authoritative schedule starts');
assert.equal(coincidentTurn.state_delta.fatigue_delta,2,'legitimate completed-action effects must survive a coincident schedule boundary');
assert.deepEqual(coincidentTurn.state_delta.stat_progress,[{stat:'신체',amount:1}],'completed growth must survive a coincident schedule boundary');
assert.match(coincidentTurn.scene_summary,/기사과 필수 수업의 시작 시점/,'a coincident but unsurfaced schedule must become visible');
assert.equal(coincidentScheduleIntent.reconciliationReason,'schedule-boundary','coincident schedule reconciliation must be reported as a schedule boundary');
let turn={state_delta:{advance_minutes:0},choices:[]};
applySceneMomentumTimeFloor({action:'쉰다.',saveState:boundarySave},turn,'game');
assert.equal(turn.state_delta.advance_minutes,10,'forced downtime floor must stop at the next authoritative schedule boundary');
turn={state_delta:{advance_minutes:0},choices:[]};
applySceneMomentumTimeFloor({action:'두 시간 쉰다.',saveState:boundarySave},turn,'game');
assert.equal(turn.state_delta.advance_minutes,10,'native-Korean long rest must stop at the next authoritative schedule boundary');

const interruptedSleepEvent={id:'morning-class',title:'기사과 필수 수업',date:'1285-03-01',time:'10:00',kind:'academic',status:'scheduled'},interruptedSleepSave={pc:knightPc,world:{date:'1285-03-01',time:'09:00',location:'개인실'},scheduleContext:{due:[],upcoming:[interruptedSleepEvent]},scheduledEvents:[interruptedSleepEvent]},interruptedScheduleScene=[{kind:'narration',text:'10시를 알리는 종이 울리고 기사과 필수 수업이 시작되었다.'}];
turn={scene_title:'기사과 필수 수업 시작',scene_summary:'수업 종이 울렸다.',scene:interruptedScheduleScene,state_delta:{advance_minutes:60,fatigue_delta:-3,items_add:['숙면 보상'],active_events_add:['morning-class'],scheduled_events_remove:['morning-class']},choices:['수업에 참석한다','조금 더 눕는다','상황을 확인한다'],event_progress:{event_instance_id:'morning-class',active_beat:'start',completed_beats:[]}};
const interruptedSleepIntent=applySceneMomentumTimeFloor({action:'8시간 동안 잠을 잔다.',saveState:interruptedSleepSave},turn,'game');
assert.equal(turn.state_delta.advance_minutes,60,'an earlier manifested class must truncate explicit sleep at the exact schedule boundary');
assert.equal(turn.state_delta.fatigue_delta,0,'premature sleep recovery must not cross the interruption boundary');
assert.deepEqual(turn.state_delta.items_add,[],'premature sleep completion rewards must fail closed at the interruption');
assert.deepEqual(turn.state_delta.active_events_add,['morning-class'],'a validated nonterminal schedule start must remain active');
assert.deepEqual(turn.state_delta.scheduled_events_remove,['morning-class'],'a validated started schedule may leave the pending bucket');
assert.equal(turn.event_progress.event_instance_id,'morning-class','nonterminal structured schedule progress must survive truncation reconciliation');
assert.strictEqual(turn.scene,interruptedScheduleScene,'validated schedule-start narration must remain visible');
assert.deepEqual(turn.choices,['수업에 참석한다','조금 더 눕는다','상황을 확인한다'],'the schedule response choices must remain available');
assert.equal(interruptedSleepIntent.runtimeSceneTrusted,true,'validated schedule-start context must reach runtime synthesis');
assert.equal(interruptedSleepIntent.returnedSceneReconciled,false,'a trusted surfaced schedule scene must not be replaced by a generic boundary');
const overrunScheduleScene=[
  {kind:'narration',text:'잠이 들고 한 시간이 흘렀다.'},
  {kind:'narration',text:'10시를 알리는 종이 울리고 기사과 필수 수업이 시작되었다.'},
  {kind:'narration',text:'두 시간이 더 흐른 뒤 왕도로 이동했다.'},
  {kind:'dialogue',speaker_key:'emily',text:'에밀리가 왕도에서 말을 걸었다.'},
];
turn={scene_title:'왕도에서의 대화',scene_summary:'수업 뒤 왕도로 가서 에밀리와 만났다.',scene:overrunScheduleScene,state_delta:{advance_minutes:180,new_location:'왕도',npc_state_updates:[{npc_key:'emily',location:'왕도'}],active_events_add:['morning-class'],scheduled_events_remove:['morning-class']},choices:['에밀리에게 답한다','왕도를 둘러본다'],event_progress:{event_instance_id:'morning-class',active_beat:'start',completed_beats:[]}};
const trimmedScheduleIntent=applySceneMomentumTimeFloor({action:'8시간 동안 잠을 잔다.',saveState:interruptedSleepSave},turn,'game');
assert.equal(turn.state_delta.advance_minutes,60,'a surfaced schedule must rewind the clock before later generated scene rows');
assert.equal(turn.state_delta.new_location,null,'post-boundary travel must not survive schedule reconciliation');
assert.deepEqual(turn.state_delta.npc_state_updates,[],'post-boundary NPC effects must not survive schedule reconciliation');
assert.equal(turn.scene.length,2,'only pre-boundary and validated boundary narration may remain visible');
assert.match(turn.scene.at(-1).text,/필수 수업이 시작되었다/,'the validated schedule-start row must remain visible');
assert.doesNotMatch(JSON.stringify(turn.scene),/왕도로 이동|왕도에서 말을/,'post-boundary narration must be removed');
assert.deepEqual(turn.choices,[],'choices produced after the boundary must be removed');
assert.equal(turn.scene_title,'기사과 필수 수업 시작','a trimmed response must expose the authoritative boundary title');
assert.equal(trimmedScheduleIntent.runtimeSceneTrusted,true,'the trimmed schedule prefix remains safe for runtime synthesis');
assert.equal(trimmedScheduleIntent.returnedSceneReconciled,true,'removing post-boundary rows must be reported as visible reconciliation');
turn={scene_title:'왕도 도착',scene_summary:'왕도에서 에밀리를 만났다.',scene:[{kind:'narration',text:'세 시간이 지나 왕도에 도착했다.'}],state_delta:{advance_minutes:180,new_location:'왕도',active_events_add:['morning-class'],scheduled_events_remove:['morning-class']},choices:['에밀리에게 말한다'],event_progress:{event_instance_id:'morning-class',active_beat:'start',completed_beats:[]}};
const structuredOnlyScheduleIntent=applySceneMomentumTimeFloor({action:'8시간 동안 잠을 잔다.',saveState:interruptedSleepSave},turn,'game');
assert.equal(turn.state_delta.advance_minutes,60,'structured schedule progress must still establish the exact boundary');
assert.equal(turn.event_progress.event_instance_id,'morning-class','validated structured schedule progress must survive even when its narration is absent');
assert.equal(structuredOnlyScheduleIntent.runtimeSceneTrusted,false,'structured progress alone must not make unrelated visible narration trustworthy');
assert.equal(turn.scene_title,'일정 경계','an unsurfaced structured boundary must use deterministic visible reconciliation');
assert.doesNotMatch(JSON.stringify(turn.scene),/왕도|에밀리/,'post-boundary narration must be removed when no boundary scene can be validated');

for(const [action,prose,elapsed] of [
  ['1시간 동안 훈련한다.','리나는 먼저 훈련을 마쳤다.',10],
  ['8시간 동안 잠을 잔다.','리나는 먼저 잠에서 깨어났다.',60],
  ['30분 동안 식사를 한다.','리나는 먼저 식사를 마쳤다.',10],
  ['1시간 동안 수업을 듣는다.','리나는 먼저 수업을 마쳤다.',10],
  ['1시간 동안 회의를 한다.','리나는 먼저 회의를 마쳤다.',10],
  ['30분 동안 빵을 먹는다.','리나는 먼저 빵을 모두 먹었다.',10],
]){
  turn={scene:[{kind:'narration',text:prose}],state_delta:{advance_minutes:elapsed},choices:['계속한다','상황을 본다','그만둔다']};
  applySceneMomentumTimeFloor({action,saveState:{pc:{name:'카인'},world:{date:'1285-03-01',time:'09:00'},scheduleContext:{due:[],upcoming:[]}}},turn,'game');
  assert.equal(turn.state_delta.advance_minutes,elapsed,`third-party completion must not complete the player's timed action: ${prose}`);
}
turn={scene:[{kind:'narration',text:'카인은 훈련을 마쳤다.'}],state_delta:{advance_minutes:10},choices:['다음 훈련을 고른다']};
applySceneMomentumTimeFloor({action:'1시간 동안 훈련한다.',saveState:{pc:{name:'카인'},world:{date:'1285-03-01',time:'09:00'},scheduleContext:{due:[],upcoming:[]}}},turn,'game');
assert.equal(turn.state_delta.advance_minutes,60,'the saved player subject must remain valid completion evidence');

const ownClass={id:'basic-class',title:'기사과 기초 수업',date:'1285-03-01',time:'10:00',kind:'academic',status:'scheduled'};
const ownClassSave={pc:knightPc,world:{date:'1285-03-01',time:'09:00',location:'기숙사'},scheduleContext:{due:[],upcoming:[ownClass]},scheduledEvents:[ownClass]};
const ownClassAction='10시에 기초 수업에 참석한다.';
const ownClassIntent=classifySceneIntent(ownClassAction,{location:'기숙사',currentTime:'09:00'});
assert.equal(nextScheduleBoundaryMinutes(ownClassSave,{futureOnly:true,action:ownClassAction,intent:ownClassIntent}),null,'an explicitly requested scheduled activity must not interrupt itself at its own start');
const modifiedOwnClassAction='오전 10시에 기사과의 기초 수업을 듣는다.';
const modifiedOwnClassIntent=classifySceneIntent(modifiedOwnClassAction,{location:'기숙사',currentTime:'09:00'});
assert.equal(nextScheduleBoundaryMinutes(ownClassSave,{futureOnly:true,action:modifiedOwnClassAction,intent:modifiedOwnClassIntent}),null,'temporal modifiers and Korean possessive particles must not make the requested class interrupt itself');
const genericOwnClassAction='10시에 수업을 듣는다.';
const genericOwnClassIntent=classifySceneIntent(genericOwnClassAction,{location:'기숙사',currentTime:'09:00'});
assert.equal(nextScheduleBoundaryMinutes(ownClassSave,{futureOnly:true,action:genericOwnClassAction,intent:genericOwnClassIntent}),null,'a unique same-time class must be recognized when the request has no identifying title token');
const compoundOwnClassAction='9시에 아침을 먹고 10시에 기사과의 기초 수업을 듣는다.';
const compoundOwnClassIntent=classifySceneIntent(compoundOwnClassAction,{location:'기숙사',currentTime:'09:00'});
assert.equal(nextScheduleBoundaryMinutes(ownClassSave,{futureOnly:true,action:compoundOwnClassAction,intent:compoundOwnClassIntent}),null,'tokens from an earlier compound-action clause must not make the selected terminal class interrupt itself');
const otherSameTimeClass={id:'advanced-class',title:'기사과 고급 수업',date:'1285-03-01',time:'10:00',kind:'academic',status:'scheduled'};
assert.equal(nextScheduleBoundaryMinutes({...ownClassSave,scheduleContext:{due:[],upcoming:[ownClass,otherSameTimeClass]},scheduledEvents:[ownClass,otherSameTimeClass]},{futureOnly:true,action:ownClassAction,intent:ownClassIntent}),60,'a different same-time class must remain authoritative even when it shares a department token with the requested class');
assert.equal(nextScheduleBoundaryMinutes({...ownClassSave,scheduleContext:{due:[],upcoming:[ownClass,otherSameTimeClass]},scheduledEvents:[ownClass,otherSameTimeClass]},{futureOnly:true,action:genericOwnClassAction,intent:genericOwnClassIntent}),60,'a generic request must remain ambiguous when multiple same-category events share its time');
assert.doesNotMatch(buildSceneMomentumDirective({action:ownClassAction,saveState:ownClassSave}),/SCHEDULE_BOUNDARY=60min/,'the requested class start must remain part of class completion rather than become a new choice stop');
const nextDayOwnClass={id:'next-basic-class',title:'기사과 기초 수업',date:'1285-03-02',time:'08:00',kind:'academic',status:'scheduled'};
const nextDayOwnClassSave={pc:knightPc,world:{date:'1285-03-01',time:'09:00',location:'기숙사'},scheduleContext:{due:[],upcoming:[nextDayOwnClass]},scheduledEvents:[nextDayOwnClass]};
const nextDayOwnClassAction='내일 오전 8시에 기사과 기초 수업을 듣는다.';
const nextDayOwnClassIntent=classifySceneIntent(nextDayOwnClassAction,{location:'기숙사',currentTime:'09:00'});
assert.equal(nextScheduleBoundaryMinutes(nextDayOwnClassSave,{futureOnly:true,action:nextDayOwnClassAction,intent:nextDayOwnClassIntent}),null,'a date-qualified requested class must not interrupt itself at its own absolute start time');
turn={scene_title:'다음 날 기초 수업',scene:[{kind:'narration',text:'다음 날 기사과 기초 수업을 마쳤다.'}],state_delta:{advance_minutes:1425,skill_experience:[{skill:'검술',amount:1}]},choices:[]};
applySceneMomentumTimeFloor({action:nextDayOwnClassAction,saveState:nextDayOwnClassSave},turn,'game');
