const nextDayOwnRestSave={pc:knightPc,world:{date:'1285-03-01',time:'09:00',location:'기숙사'},scheduleContext:{due:[],upcoming:[nextDayOwnRest]},scheduledEvents:[nextDayOwnRest]};
